const $=id=>document.getElementById(id),frame=$('game');let ready=false,theme='graphic',car='porsche',peak=0;
const child=()=>frame.contentDocument,win=()=>frame.contentWindow;
function resume(){if(ready&&!child().getElementById('pause-menu').hidden)child().getElementById('resume').click();}
function style(){child().querySelector('.lever-up').textContent='R 후진';child().querySelector('.lever-down').textContent='드리프트';const node=child().getElementById('review-graphic-theme');node.disabled=theme==='original';child().getElementById('thumb-steering').setAttribute('aria-label',theme==='graphic'?'좌우 드래그 조향':'곡선 엄지 슬라이드 조향');document.querySelectorAll('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===theme)));requestAnimationFrame(resume);}
function start(){const d=child();if(!d.getElementById('result').hidden)d.getElementById('result-menu').click();else if(d.getElementById('menu').hidden){if(d.getElementById('pause-menu').hidden)d.getElementById('pause').click();d.getElementById('back-menu').click();}if(!d.getElementById('welcome').hidden)d.getElementById('enter-garage').click();d.querySelector('[data-car="'+car+'"]').click();d.getElementById('auto-throttle').checked=false;d.getElementById('auto-throttle').dispatchEvent(new(win().Event)('change',{bubbles:true}));d.getElementById('start').click();$('car').textContent=car==='porsche'?'포르쉐':'페라리';requestAnimationFrame(resume);}
frame.addEventListener('load',async()=>{const d=child();const styleNode=d.createElement('link');styleNode.id='review-graphic-theme';styleNode.rel='stylesheet';styleNode.href=new URL('../../game-controls.css?v=game-controls-3',location.href).href;d.head.append(styleNode);for(let i=0;i<900;i++){if(!d.getElementById('enter-garage').disabled){ready=true;style();start();$('status').textContent='가속을 눌러 출발 · 직사각형 조향·보조 레일 · 드래그 동작 유지';return;}await new Promise(r=>setTimeout(r,100));}$('status').textContent='불러오기가 끝나지 않았습니다. 다시 열어 주세요.';});
for(const b of document.querySelectorAll('[data-theme]'))b.onclick=()=>{theme=b.dataset.theme;if(ready)style();};
$('car').onclick=()=>{if(!ready)return;car=car==='porsche'?'tavaculo':'porsche';start();};$('restart').onclick=()=>{if(ready)start();};$('camera').onclick=()=>{if(ready){child().getElementById('camera').click();requestAnimationFrame(resume);}};
setInterval(()=>{if(!ready)return;const s=win().__raceQA?.snapshot();if(!s)return;peak=Math.max(peak,Math.abs(s.steeringControl?.value||0));$('controls-state').textContent=JSON.stringify({ready,theme,car,mode:s.mode,view:s.view,steering:s.steeringControl,peak,storage:'memory-only',errors:JSON.parse(child().getElementById('city-errors').textContent)});},200);
frame.src='../mixed-city/?v=mixed-city-3&qa=1';
